// lz-compress: greedy LZ77 over a generated byte buffer (see lz-compress.mi).

// clock_gettime is POSIX: strict C17 headers declare it only when asked.
#define _POSIX_C_SOURCE 200809L

#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define CHECKSUM_LEN 64

static uint8_t *generated_input(long n) {
    uint8_t *data = malloc((size_t)n);
    if (data == NULL) {
        abort();
    }
    long len = 0;
    int64_t state = 11;
    while (len < n) {
        state = state * 48271 % 2147483647;
        if (len > 64 && state % 4 == 0) {
            long back = 1 + (state / 4) % 60;
            long length = 3 + (state / 256) % 20;
            for (long k = 0; k < length && len < n; k++) {
                data[len] = data[len - back];
                len++;
            }
        } else {
            data[len++] = (uint8_t)(97 + state % 16);
        }
    }
    return data;
}

static void kernel(long n, char *checksum) {
    uint8_t *data = generated_input(n);
    int64_t literals = 0, matches = 0, hash = 0;
    long pos = 0;
    while (pos < n) {
        long best_length = 0, best_distance = 0;
        for (long start = pos > 255 ? pos - 255 : 0; start < pos; start++) {
            long length = 0;
            while (pos + length < n && length < 255 && data[start + length] == data[pos + length]) {
                length++;
            }
            if (length > best_length) {
                best_length = length;
                best_distance = pos - start;
            }
        }
        if (best_length >= 3) {
            matches += 1;
            hash = (hash * 31 + best_distance * 256 + best_length) % 1000000007;
            pos += best_length;
        } else {
            literals += 1;
            hash = (hash * 31 + data[pos]) % 1000000007;
            pos += 1;
        }
    }
    snprintf(checksum, CHECKSUM_LEN, "%lld %lld %lld", (long long)literals, (long long)matches, (long long)hash);
    free(data);
}

static int64_t now_ns(void) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (int64_t)ts.tv_sec * 1000000000 + ts.tv_nsec;
}

static void run_hot(long n, char *expected) {
    char checksum[CHECKSUM_LEN];
    kernel(n, expected);
    int agree = 1;
    for (int i = 1; i < 5; i++) {
        kernel(n, checksum);
        agree = agree && strcmp(checksum, expected) == 0;
    }
    for (int i = 0; i < 5; i++) {
        int64_t start = now_ns();
        kernel(n, checksum);
        int64_t elapsed = now_ns() - start;
        fprintf(stderr, "hot_ns=%lld\n", (long long)elapsed);
        agree = agree && strcmp(checksum, expected) == 0;
    }
    if (!agree) {
        fprintf(stderr, "checksum differs between iterations\n");
        exit(1);
    }
}

int main(int argc, char **argv) {
    FILE *f = fopen(argv[1], "r");
    long n = 0;
    if (f == NULL || fscanf(f, "%ld", &n) != 1) {
        return 2;
    }
    fclose(f);
    char checksum[CHECKSUM_LEN];
    if (argc > 2 && strcmp(argv[2], "hot") == 0) {
        run_hot(n, checksum);
    } else {
        kernel(n, checksum);
    }
    printf("%s\n", checksum);
    return 0;
}
